# So 90.1K and 542.2K suggest that:
# if K has a decimal part >= .05, show 1 decimal
# Otherwise show integer
# Actually let me reconsider: maybe it's showing 1 decimal always for K if < 100?

def fmtsize(n):
    if n < 1024:
        return f'{n}B'
    elif n < 1024*1024:
        k = n / 1024.0
        # Check if decimal part is significant
        if k < 100.0:
            # Show 1 decimal if there's a fractional part
            tenths = round(k * 10) % 10
            if tenths != 0:
                return f'{k:.1f}K'
            else:
                return f'{int(round(k))}K'
        else:
            return f'{int(round(k))}K'
    elif n < 1024*1024*1024:
        m = n / (1024.0*1024.0)
        if m < 10.0:
            return f'{m:.2f}M'
        else:
            return f'{int(round(m))}M'
    else:
        g = n / (1024.0*1024.0*1024.0)
        if g < 10.0:
            return f'{g:.2f}G'
        else:
            return f'{int(round(g))}G'

tests = [
    (6, '6B'),
    (92312, '90.1K'),
    (807936, '789K'),
    (555176, '542.2K'),
    (5834688, '5.56M'),
    (1656, '1.6K'),
    (608, '608B'),
    (4096, '4K'),
    (8192, '8K'),
]
for size, expected in tests:
    result = fmtsize(size)
    ok = 'OK' if result == expected else 'FAIL'
    print(f'{ok}: {size} -> {result} (expected {expected})')
"

