/* Format file size human-readable */
static void fmtsize(off_t n, char *buf, int buflen) {
    if (n == 0) {
        snprintf(buf, buflen, "0B");
    } else if (n < 1024) {
        snprintf(buf, buflen, "%lldB", (long long)n);
    } else if (n < 1024LL * 1024) {
        double k = (double)n / 1024.0;
        int tenths = (int)(k * 10.0 + 0.5) % 10;
        if (tenths != 0)
            snprintf(buf, buflen, "%.1fK", k);
        else
            snprintf(buf, buflen, "%lldK", (long long)(k + 0.5));
    } else if (n < 1024LL * 1024 * 1024) {
        double m = (double)n / (1024.0 * 1024.0);
        if (m < 10.0)
            snprintf(buf, buflen, "%.2fM", m);
        else
            snprintf(buf, buflen, "%lldM", (long long)(m + 0.5));
    } else {
        double g = (double)n / (1024.0 * 1024.0 * 1024.0);
        if (g < 10.0)
            snprintf(buf, buflen, "%.2fG", g);
        else
            snprintf(buf, buflen, "%lldG", (long long)(g + 0.5));
