    else if (S_ISDIR(mode)) type = 'd';
    else if (S_ISLNK(mode)) type = 'l';
    else if (S_ISBLK(mode)) type = 'b';
    else if (S_ISCHR(mode)) type = 'c';
    else if (S_ISFIFO(mode)) type = 'p';
    else if (S_ISSOCK(mode)) type = 's';
    else type = '?';
    snprintf(buf, 11, "%c%c%c%c%c%c%c%c%c%c",
        type,
        (mode & S_IRUSR) ? 'r' : '-',
        (mode & S_IWUSR) ? 'w' : '-',
        (mode & S_IXUSR) ? ((mode & S_ISUID) ? 's' : 'x') : ((mode & S_ISUID) ? 'S' : '-'),
        (mode & S_IRGRP) ? 'r' : '-',
        (mode & S_IWGRP) ? 'w' : '-',
        (mode & S_IXGRP) ? ((mode & S_ISGID) ? 's' : 'x') : ((mode & S_ISGID) ? 'S' : '-'),
        (mode & S_IROTH) ? 'r' : '-',
        (mode & S_IWOTH) ? 'w' : '-',
        (mode & S_IXOTH) ? ((mode & S_ISVTX) ? 't' : 'x') : ((mode & S_ISVTX) ? 'T' : '-'));
}

/* Format time */
static void fmt_time(time_t t, char *buf, int buflen) {
    struct tm *tm = localtime(&t);
    strftime(buf, buflen, "%Y-%m-%d %H:%M", tm);
}

/* Get time based on timetype */
static time_t get_entry_time(const Entry *e) {
    switch (cfg_timetype) {
    case TIME_ACCESS: return e->sb.st_atime;
    case TIME_CHANGE: return e->sb.st_ctime;
    default:          return e->sb.st_mtime;
    }
}

/* Compare entries for sorting */
static int sort_by = SORT_NONE;
static int sort_rev = 0;
static int sort_numericfirst = 1;

/* Natural/version sort comparison */
static int numcmp(const char *a, const char *b) {
    while (*a && *b) {
        if (isdigit((unsigned char)*a) && isdigit((unsigned char)*b)) {
            /* numeric compare */
            long na = strtol(a, (char **)&a, 10);
            long nb = strtol(b, (char **)&b, 10);
            if (na != nb) return (na > nb) - (na < nb);
        } else {
            int ca = tolower((unsigned char)*a);
            int cb = tolower((unsigned char)*b);
            if (ca != cb) return (ca > cb) - (ca < cb);
            a++; b++;
        }
    }
    return (*a == '\0') - (*b == '\0');
}

static int entry_cmp(const void *va, const void *vb) {
    const Entry *a = (const Entry *)va;
    const Entry *b = (const Entry *)vb;
    int adir = S_ISDIR(a->sb.st_mode) || (a->flags & 2 && S_ISDIR(a->sb.st_mode));
    int bdir = S_ISDIR(b->sb.st_mode) || (b->flags & 2 && S_ISDIR(b->sb.st_mode));

    /* Directories first */
    if (adir != bdir)
        return sort_rev ? (adir - bdir) : (bdir - adir);

    int cmp = 0;
    switch (sort_by) {
    case SORT_SIZE:
        if (a->sb.st_size != b->sb.st_size)
            cmp = (a->sb.st_size > b->sb.st_size) - (a->sb.st_size < b->sb.st_size);
        else
            cmp = strcasecmp(a->name, b->name);
        break;
    case SORT_TIME:
        {
            time_t ta = 0, tb = 0;
            switch (cfg_timetype) {
            case TIME_ACCESS: ta = a->sb.st_atime; tb = b->sb.st_atime; break;
            case TIME_CHANGE: ta = a->sb.st_ctime; tb = b->sb.st_ctime; break;
            default:          ta = a->sb.st_mtime; tb = b->sb.st_mtime; break;
            }
            if (ta != tb)
                cmp = (ta > tb) - (ta < tb);
            else
                cmp = strcasecmp(a->name, b->name);
        }
        break;
    case SORT_EXT:
        {
            const char *ea = strrchr(a->name, '.');
            const char *eb = strrchr(b->name, '.');
            if (ea && eb)
                cmp = strcasecmp(ea, eb);
            else if (ea)
                cmp = 1;
            else if (eb)
                cmp = -1;
            if (cmp == 0)
                cmp = strcasecmp(a->name, b->name);
        }
        break;
    case SORT_VER:
        cmp = numcmp(a->name, b->name);
        break;
    default:
        /* Default: numeric-first natural sort */
        {
            /* Check if both names start with digits */
            int anum = isdigit((unsigned char)a->name[0]);
            int bnum = isdigit((unsigned char)b->name[0]);
            if (anum && bnum)
                cmp = numcmp(a->name, b->name);
            else if (anum)
                cmp = -1;
            else if (bnum)
                cmp = 1;
            else
                cmp = strcasecmp(a->name, b->name);
        }
        break;
    }

    return sort_rev ? -cmp : cmp;
}

/* Filter matching */
static int match_filter(const char *name, const char *filter, int regex_mode, int fuzzy_mode) {
    if (!filter || !filter[0]) return 1;
    if (regex_mode) {
        regex_t re;
        int r = regcomp(&re, filter, REG_EXTENDED | REG_NOSUB | REG_ICASE);
        if (r) return 0;
        r = regexec(&re, name, 0, NULL, 0);
        regfree(&re);
        return r == 0;
    }
    if (fuzzy_mode) {
        /* in-order fuzzy match */
        const char *f = filter;
        const char *n = name;
        while (*f && *n) {
            if (tolower((unsigned char)*f) == tolower((unsigned char)*n))
                f++;
            n++;
        }
        return *f == '\0';
    }
    /* Default: case-insensitive substring match */
    char lname[NAME_MAX + 1], lfilt[FILTER_LEN];
    size_t i;
    for (i = 0; name[i] && i < NAME_MAX; i++)
        lname[i] = tolower((unsigned char)name[i]);
    lname[i] = '\0';
    for (i = 0; filter[i] && i < FILTER_LEN - 1; i++)
        lfilt[i] = tolower((unsigned char)filter[i]);
    lfilt[i] = '\0';
    return strstr(lname, lfilt) != NULL;
}

