        if (c->filter[0] && !match_filter(de->d_name, c->filter, cfg_regex, cfg_fuzzy))
            continue;

        if (count >= capacity) {
            capacity += ENTRY_INCR;
            Entry *tmp = realloc(c->entries, capacity * sizeof(Entry));
            if (!tmp) break;
            c->entries = tmp;
        }

        Entry *e = &c->entries[count];
        e->name = strdup(de->d_name);
        if (!e->name) continue;
        e->flags = 0;
        e->du = 0;

        char fullpath[PATH_MAX];
        snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, de->d_name);

        if (lstat(fullpath, &e->sb) != 0) {
            memset(&e->sb, 0, sizeof(e->sb));
        }

        if (S_ISLNK(e->sb.st_mode)) {
            e->flags |= 2; /* symlink */
            /* Also get target stat */
            struct stat tsb;
            if (stat(fullpath, &tsb) == 0) {
                /* Use target for type, keep lstat for size/time */
                /* but keep the link flag */
            }
        }

        count++;
    }
    closedir(dp);

    c->nentries = count;

    /* Sort */
    sort_by = c->sortby;
    sort_rev = c->sortrev;
    if (count > 0)
        qsort(c->entries, count, sizeof(Entry), entry_cmp);

    return count;
}

/* Find entry index by name */
static int find_entry(Context *c, const char *name) {
    for (int i = 0; i < c->nentries; i++) {
        if (strcmp(c->entries[i].name, name) == 0)
            return i;
    }
    return 0;
}

/* Selection management */
static char **sel_entries = NULL;
static int sel_n = 0;
static int sel_cap = 0;

static void sel_add(const char *path) {
    /* Check if already selected */
    for (int i = 0; i < sel_n; i++) {
        if (sel_entries[i] && strcmp(sel_entries[i], path) == 0)
            return;
    }
    if (sel_n >= sel_cap) {
        sel_cap += 32;
        char **tmp = realloc(sel_entries, sel_cap * sizeof(char *));
        if (!tmp) return;
        sel_entries = tmp;
    }
    sel_entries[sel_n++] = strdup(path);
}

static void sel_remove(const char *path) {
    for (int i = 0; i < sel_n; i++) {
        if (sel_entries[i] && strcmp(sel_entries[i], path) == 0) {
            free(sel_entries[i]);
            sel_entries[i] = NULL;
            /* compact */
            for (int j = i; j < sel_n - 1; j++)
                sel_entries[j] = sel_entries[j + 1];
            sel_n--;
            return;
        }
    }
}

static int sel_isselected(const char *path) {
    for (int i = 0; i < sel_n; i++) {
        if (sel_entries[i] && strcmp(sel_entries[i], path) == 0)
            return 1;
    }
    return 0;
}

static void sel_clear(void) {
    for (int i = 0; i < sel_n; i++)
        free(sel_entries[i]);
    sel_n = 0;
}

static void sel_write(const char *file, int nullsep) {
    if (!file || !file[0]) return;
    FILE *fp;
    if (strcmp(file, "-") == 0)
        fp = stdout;
    else
        fp = fopen(file, "w");
    if (!fp) return;
    for (int i = 0; i < sel_n; i++) {
        if (sel_entries[i]) {
            fputs(sel_entries[i], fp);
            fputc(nullsep ? '\0' : '\n', fp);
        }
    }
    if (fp != stdout) fclose(fp);
}

/* Write selection to selpath */
static void sync_sel(void) {
    if (selpath[0]) {
        FILE *fp = fopen(selpath, "w");
        if (!fp) return;
        for (int i = 0; i < sel_n; i++) {
            if (sel_entries[i]) {
                fputs(sel_entries[i], fp);
                fputc('\n', fp);
            }
        }
        fclose(fp);
    }
}

/* Toggle selection for current entry */
static void toggle_sel(Context *c) {
    if (c->cur < 0 || c->cur >= c->nentries) return;
    Entry *e = &c->entries[c->cur];
    char fullpath[PATH_MAX];
    snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);

    if (e->flags & 1) {
        e->flags &= ~1;
        sel_remove(fullpath);
    } else {
        e->flags |= 1;
        sel_add(fullpath);
    }
    sync_sel();
}

