        waddch(mainwin, ' ');
        wattroff(mainwin, A_BOLD | A_REVERSE | COLOR_PAIR(ctx_color[curcxt]));
    } else if (issel) {
        wattron(mainwin, A_BOLD);
        waddch(mainwin, '+');
        wattroff(mainwin, A_BOLD);
    } else {
        waddch(mainwin, ' ');
    }

    /* Detail mode */
    if (c->dtoggle) {
        /* Date/time */
        char tmbuf[32];
        time_t t = get_entry_time(e);
        fmt_time(t, tmbuf, sizeof(tmbuf));

        if (iscur)
            wattron(mainwin, A_BOLD | A_REVERSE | A_DIM);
        else
            wattron(mainwin, A_DIM);
        wprintw(mainwin, "%s", tmbuf);
        if (iscur)
            wattroff(mainwin, A_BOLD | A_REVERSE | A_DIM);
        else
            wattroff(mainwin, A_DIM);

        waddstr(mainwin, "  ");

        /* Octal permissions */
        char pbuf[8];
        fmt_perms_octal(e->sb.st_mode, pbuf);

        if (iscur)
            wattron(mainwin, A_BOLD | A_REVERSE | A_DIM);
        else
            wattron(mainwin, A_DIM);
        wprintw(mainwin, "%s", pbuf);
        if (iscur)
            wattroff(mainwin, A_BOLD | A_REVERSE | A_DIM);
        else
            wattroff(mainwin, A_DIM);

        /* Size (9 chars right-aligned) */
        char szstr[32];
        if (islink) {
            strcpy(szstr, "@");
        } else if (c->du_mode == 2) {
            /* disk usage mode */
            fmtsize(e->du > 0 ? e->du : 0, szstr, sizeof(szstr));
        } else if (c->du_mode == 1) {
            /* apparent size mode */
            fmtsize(e->sb.st_size, szstr, sizeof(szstr));
        } else {
            fmtsize(e->sb.st_size, szstr, sizeof(szstr));
        }

        if (iscur)
            wattron(mainwin, A_BOLD | A_REVERSE | A_DIM);
        else
            wattron(mainwin, A_DIM);
        wprintw(mainwin, "%9s", szstr);
        if (iscur)
            wattroff(mainwin, A_BOLD | A_REVERSE | A_DIM);
        else
            wattroff(mainwin, A_DIM);

        waddstr(mainwin, "  ");
    }

