    attr_t nameattr = A_NORMAL;
    int namepair = 0;

    if (isdir || issymdir) {
        nameattr = A_BOLD;
        namepair = ctx_color[curcxt];
    } else if (islink) {
        nameattr = A_NORMAL;
        namepair = ctx_color[curcxt];
    } else if (isexec) {
        nameattr = A_NORMAL;
        namepair = COLOR_GREEN;
    }

    if (iscur) {
        wattron(mainwin, A_BOLD | A_REVERSE | COLOR_PAIR(namepair));
    } else if (issel) {
        wattron(mainwin, A_BOLD | COLOR_PAIR(namepair));
    } else {
        if (namepair)
            wattron(mainwin, nameattr | COLOR_PAIR(namepair));
        else
            wattron(mainwin, nameattr);
    }

    waddstr(mainwin, e->name);

    /* Suffix: / for dirs, @ for symlinks */
    if (isdir || issymdir) {
        waddch(mainwin, '/');
    } else if (islink) {
        waddch(mainwin, '@');
    }

    if (iscur) {
        wattroff(mainwin, A_BOLD | A_REVERSE | COLOR_PAIR(namepair));
    } else if (issel) {
        wattroff(mainwin, A_BOLD | COLOR_PAIR(namepair));
    } else {
        if (namepair)
            wattroff(mainwin, nameattr | COLOR_PAIR(namepair));
        else
            wattroff(mainwin, nameattr);
    }
}

/* Draw status bar */
static void draw_status(Context *c) {
    int row = LINES - 1;
    wmove(mainwin, row, 0);
    wclrtoeol(mainwin);

    wattron(mainwin, COLOR_PAIR(ctx_color[curcxt]));

    /* pos/total */
    wprintw(mainwin, "%d/%d", c->nentries > 0 ? c->cur + 1 : 0, c->nentries);

    /* Flags */
    char flags[32] = "";
    int fi = 0;

    /* Sort indicator */
    switch (c->sortby) {
    case SORT_SIZE: flags[fi++] = 'S'; break;
    case SORT_TIME: flags[fi++] = 'M'; break;
    case SORT_EXT:  flags[fi++] = 'E'; break;
    case SORT_VER:  flags[fi++] = 'V'; break;
    default: break;
    }
    if (c->sortrev && c->sortby != SORT_NONE) flags[fi++] = 'R';
    else if (c->sortrev) flags[fi++] = 'R';

    /* DU mode */
    if (c->du_mode == 1) { flags[fi++] = 'a'; flags[fi++] = 'u'; }
    else if (c->du_mode == 2) { flags[fi++] = 'd'; flags[fi++] = 'u'; }

    /* Hidden */
    if (c->showhidden) flags[fi++] = 'H';
    flags[fi] = '\0';

    /* Space + flags */
    if (flags[0]) {
        wprintw(mainwin, " %s", flags);
    }

    /* Entry info */
    if (c->nentries > 0 && c->cur < c->nentries) {
        Entry *e = &c->entries[c->cur];

        /* Show selection count if any */
        if (sel_n > 0) {
            wprintw(mainwin, "   +%d", sel_n);
        } else {
            waddstr(mainwin, "  ");
        }

        /* Time */
        char tmbuf[32];
        time_t t = get_entry_time(e);
        fmt_time(t, tmbuf, sizeof(tmbuf));
        wattron(mainwin, A_REVERSE);
        wprintw(mainwin, "%s", tmbuf);
        wattroff(mainwin, A_REVERSE);

        waddch(mainwin, ' ');

        /* Permissions */
        char pbuf[12];
        fmt_perms_rwx(e->sb.st_mode, pbuf);
        wprintw(mainwin, "%s", pbuf);

        /* User:group if -U */
        if (cfg_showuser) {
            struct passwd *pw = getpwuid(e->sb.st_uid);
            struct group  *gr = getgrgid(e->sb.st_gid);
            const char *un = pw ? pw->pw_name : "?";
            const char *gn = gr ? gr->gr_name : "?";
            wprintw(mainwin, " %s:%s", un, gn);
        }

        waddch(mainwin, ' ');

        /* Size */
        char szstr[32];
        int islink = (e->flags & 2);
        if (islink) {
            /* show symlink size */
            fmtsize(e->sb.st_size, szstr, sizeof(szstr));
        } else if (c->du_mode == 2) {
            fmtsize(e->du > 0 ? e->du : 0, szstr, sizeof(szstr));
        } else {
            fmtsize(e->sb.st_size, szstr, sizeof(szstr));
        }
        wprintw(mainwin, "%s", szstr);

        /* Symlink target */
        if (islink) {
            char target[PATH_MAX];
            char fullpath[PATH_MAX];
            snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);
            ssize_t n = readlink(fullpath, target, sizeof(target) - 1);
            if (n > 0) {
                target[n] = '\0';
                wprintw(mainwin, " ->%s", target);
            }
        } else {
            /* Extension */
            const char *ext = strrchr(e->name, '.');
            if (ext && ext != e->name && !S_ISDIR(e->sb.st_mode))
                wprintw(mainwin, " %s", ext);
        }
    } else if (c->du_mode > 0) {
        /* Show du summary */
    }

    wattroff(mainwin, COLOR_PAIR(ctx_color[curcxt]));
}

/* Redraw entire screen */
static void redraw(Context *c) {
    int rows = LINES;
    int listrows = rows - 3; /* header + empty + status */

    werase(mainwin);

    /* Header */
    draw_header(c);

    /* Empty line after header */
    wmove(mainwin, 1, 0);
    wclrtoeol(mainwin);

    /* Adjust scroll */
    if (c->cur < c->scroll)
        c->scroll = c->cur;
    if (c->cur >= c->scroll + listrows)
        c->scroll = c->cur - listrows + 1;
    if (c->scroll < 0) c->scroll = 0;

    /* File list */
    int row = 2;
    for (int i = c->scroll; i < c->nentries && row < rows - 1; i++, row++) {
        draw_entry(c, row, i);
    }

    /* Clear remaining rows */
    for (; row < rows - 1; row++) {
        wmove(mainwin, row, 0);
        wclrtoeol(mainwin);
    }

    /* Status bar */
    draw_status(c);

    wrefresh(mainwin);
}

