            snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);
            ssize_t n = readlink(fullpath, target, sizeof(target) - 1);
            if (n > 0) {
                target[n] = '\0';
                wprintw(mainwin, " ->%s", target);
            }
        } else {
            /* Extension */
            const char *ext = strrchr(e->name, '.');
            if (ext && ext != e->name && !S_ISDIR(e->sb.st_mode))
                wprintw(mainwin, " %s", ext);
        }
    } else if (c->du_mode > 0) {
        /* Show du summary */
    }

    wattroff(mainwin, COLOR_PAIR(ctx_color[curcxt]));
}

/* Redraw entire screen */
static void redraw(Context *c) {
    int rows = LINES;
    int listrows = rows - 3; /* header + empty + status */

    werase(mainwin);

    /* Header */
    draw_header(c);

    /* Empty line after header */
    wmove(mainwin, 1, 0);
    wclrtoeol(mainwin);

    /* Adjust scroll */
    if (c->cur < c->scroll)
        c->scroll = c->cur;
    if (c->cur >= c->scroll + listrows)
        c->scroll = c->cur - listrows + 1;
    if (c->scroll < 0) c->scroll = 0;

    /* File list */
    int row = 2;
    for (int i = c->scroll; i < c->nentries && row < rows - 1; i++, row++) {
        draw_entry(c, row, i);
    }

    /* Clear remaining rows */
    for (; row < rows - 1; row++) {
        wmove(mainwin, row, 0);
        wclrtoeol(mainwin);
    }

    /* Status bar */
    draw_status(c);

    wrefresh(mainwin);
}

