    snprintf(title, sizeof(title), " %d/%d %s ", c->cur + 1, c->nentries, e->name);

    box(popup, 0, 0);
    mvwprintw(popup, 0, 1, "%s", title);

    /* Bottom bar */
    mvwprintw(popup, poph - 1, 1, "/ESC:close  arrows:scroll  n/j:next  p/k:prev");

    /* Display stat output line by line */
    int row = 1;
    char *line = statout;
    char *nl;
    while ((nl = strchr(line, '\n')) && row < poph - 1) {
        *nl = '\0';
        mvwprintw(popup, row, 2, "%.*s", popw - 4, line);
        *nl = '\n';
        line = nl + 1;
        row++;
    }

    wrefresh(popup);

    /* Input loop */
    int scroll = 0;
    /* Count lines */
    int nlines = 0;
    char *p = statout;
    while (*p) { if (*p == '\n') nlines++; p++; }

    nodelay(popup, 0);
    int ch;
    while ((ch = wgetch(popup)) != ERR) {
        if (ch == 'q' || ch == '/' || ch == 27) break;
        if (ch == KEY_DOWN || ch == 'j' || ch == 'n') {
            if (scroll < nlines - (poph - 2)) scroll++;
        } else if (ch == KEY_UP || ch == 'k' || ch == 'p') {
            if (scroll > 0) scroll--;
        } else if (ch == 'n' || ch == 'j') {
            /* Next entry */
            if (c->cur < c->nentries - 1) {
                c->cur++;
                e = &c->entries[c->cur];
                snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);
                snprintf(cmd, sizeof(cmd), "stat '%s' 2>&1", fullpath);
                run_cmd(cmd, statout, sizeof(statout));
                scroll = 0;
                nlines = 0;
                p = statout;
                while (*p) { if (*p == '\n') nlines++; p++; }
            }
        } else if (ch == 'p' || ch == 'k') {
            if (c->cur > 0) {
                c->cur--;
                e = &c->entries[c->cur];
                snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);
                snprintf(cmd, sizeof(cmd), "stat '%s' 2>&1", fullpath);
                run_cmd(cmd, statout, sizeof(statout));
                scroll = 0;
                nlines = 0;
                p = statout;
                while (*p) { if (*p == '\n') nlines++; p++; }
            }
        }

        /* Redraw popup */
        werase(popup);
        box(popup, 0, 0);
        snprintf(title, sizeof(title), " %d/%d %s ", c->cur + 1, c->nentries, e->name);
        mvwprintw(popup, 0, 1, "%s", title);
        mvwprintw(popup, poph - 1, 1, "/ESC:close  arrows:scroll  n/j:next  p/k:prev");

        row = 1;
        line = statout;
        int skip = scroll;
        while ((nl = strchr(line, '\n')) && row < poph - 1) {
            *nl = '\0';
            if (skip-- <= 0) {
                mvwprintw(popup, row, 2, "%.*s", popw - 4, line);
                row++;
            }
            *nl = '\n';
            line = nl + 1;
        }

        wrefresh(popup);
    }

    delwin(popup);
}

