/* Filter mode */
static void do_filter(Context *c) {
    int row = LINES - 1;
    char fbuf[FILTER_LEN];
    xstrlcpy(fbuf, c->filter, sizeof(fbuf));

    /* Show filter prompt */
    const char *fmode = cfg_regex ? "re" : (cfg_fuzzy ? "fz" : "str");
    char prompt[64];
    snprintf(prompt, sizeof(prompt), " str [/], ic [:]");

    wmove(mainwin, row, 0);
    wclrtoeol(mainwin);
    /* Show on right side */
    int promptlen = strlen(prompt);
    wmove(mainwin, row, COLS - promptlen);
    waddstr(mainwin, prompt);
    wmove(mainwin, row, 0);
    waddch(mainwin, '/');
    waddstr(mainwin, fbuf);
    wrefresh(mainwin);

    /* Filter input loop */
    int pos = strlen(fbuf);
    nodelay(mainwin, 0);
    int ch;

    while ((ch = wgetch(mainwin)) != ERR) {
        if (ch == '\n' || ch == KEY_ENTER) break;
        if (ch == 27) {
            /* Escape - clear filter */
            fbuf[0] = '\0';
            pos = 0;
            break;
        }
        if (ch == KEY_BACKSPACE || ch == 127 || ch == 8) {
            if (pos > 0) {
                pos--;
                fbuf[pos] = '\0';
            } else {
                /* backspace on empty filter - exit filter mode */
                break;
            }
        } else if (ch >= 32 && ch < 127 && pos < FILTER_LEN - 1) {
            fbuf[pos++] = ch;
            fbuf[pos] = '\0';
        } else if (ch == KEY_UP || ch == 'k') {
            break;
        } else if (ch == KEY_DOWN || ch == 'j') {
            break;
        } else {
            continue;
        }

        /* Update filter and redisplay */
        xstrlcpy(c->filter, fbuf, sizeof(c->filter));
        int old_cur = c->cur;
        read_dir(c);

        /* Try to keep cursor on same entry */
        if (c->nentries > 0) {
            c->cur = 0;
            c->scroll = 0;
        }

        /* Check for auto-enter on unique match */
        if (!cfg_noautoenter && c->nentries == 1 &&
            S_ISDIR(c->entries[0].sb.st_mode)) {
            /* Auto-enter the directory */
            navigate_into(c);
            fbuf[0] = '\0';
            pos = 0;
            xstrlcpy(c->filter, fbuf, sizeof(c->filter));
        }

        /* Redraw */
        int listrows = LINES - 3;
        if (c->cur < c->scroll) c->scroll = c->cur;
        if (c->cur >= c->scroll + listrows) c->scroll = c->cur - listrows + 1;

        /* Redraw header and file list */
        draw_header(c);
        wmove(mainwin, 1, 0); wclrtoeol(mainwin);
        int r2 = 2;
        for (int i = c->scroll; i < c->nentries && r2 < LINES - 1; i++, r2++)
            draw_entry(c, r2, i);
        for (; r2 < LINES - 1; r2++) { wmove(mainwin, r2, 0); wclrtoeol(mainwin); }

        /* Show filter on status line */
        wmove(mainwin, row, 0);
        wclrtoeol(mainwin);
        int pl2 = strlen(prompt);
        wmove(mainwin, row, COLS - pl2);
        waddstr(mainwin, prompt);
        wmove(mainwin, row, 0);
        waddch(mainwin, '/');
        waddstr(mainwin, fbuf);
        wrefresh(mainwin);
    }

    /* Apply final filter */
    xstrlcpy(c->filter, fbuf, sizeof(c->filter));
    read_dir(c);
    if (c->cur >= c->nentries) c->cur = c->nentries > 0 ? c->nentries - 1 : 0;
    c->scroll = 0;
}

/* Sort toggle prompt */
static void do_sort_toggle(Context *c) {
    show_msg("'a'u/'d'u/'e'xt/'r'ev/'s'z/'t'm/'v'er/'c'lr/'^T'?");
    nodelay(mainwin, 0);
    int ch = wgetch(mainwin);
    switch (ch) {
    case 'a': c->du_mode = 1; break;
    case 'd': c->du_mode = 2; break;
    case 'e': c->sortby = SORT_EXT; break;
    case 'r': c->sortrev = !c->sortrev; break;
    case 's': c->sortby = SORT_SIZE; break;
    case 't': c->sortby = SORT_TIME; break;
    case 'v': c->sortby = SORT_VER; break;
    case 'c': c->sortby = SORT_NONE; c->sortrev = 0; c->du_mode = 0; break;
    case ('T' - 64): /* Ctrl-T */
        c->sortby = SORT_NONE; c->sortrev = 0; break;
    default: break;
    }
    sort_by = c->sortby;
    sort_rev = c->sortrev;
    if (c->nentries > 0)
        qsort(c->entries, c->nentries, sizeof(Entry), entry_cmp);
}

/* Time type toggle */
static void do_time_type(Context *c) {
    char cur = 'm';
    switch (cfg_timetype) {
    case TIME_ACCESS: cur = 'a'; break;
    case TIME_CHANGE: cur = 'c'; break;
    default: cur = 'm'; break;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "'a'ccess / 'c'hange / 'm'od [%c]", cur);
    show_msg(msg);
    nodelay(mainwin, 0);
    int ch = wgetch(mainwin);
    switch (ch) {
    case 'a': cfg_timetype = TIME_ACCESS; break;
    case 'c': cfg_timetype = TIME_CHANGE; break;
    case 'm': cfg_timetype = TIME_MOD; break;
    default: break;
    }
}

/* Create new file/dir */
static void do_create(Context *c) {
    show_msg("['f'ile]/'d'ir/'s'ym/'h'ard?");
    nodelay(mainwin, 0);
    int ch = wgetch(mainwin);
    if (ch == 27) return;

    char name[NAME_MAX + 1];
    char prompt2[32];
    switch (ch) {
    case 'f': strcpy(prompt2, "name: "); break;
    case 'd': strcpy(prompt2, "mkdir: "); break;
    case 's': strcpy(prompt2, "symlink: "); break;
    case 'h': strcpy(prompt2, "hardlink: "); break;
    default: return;
    }

    if (!prompt_input(prompt2, name, sizeof(name))) return;
    if (!name[0]) return;

    char fullpath[PATH_MAX];
    snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, name);

    int ok = 0;
    switch (ch) {
    case 'f':
        {
            int fd = open(fullpath, O_CREAT | O_WRONLY, 0644);
            if (fd >= 0) { close(fd); ok = 1; }
        }
        break;
    case 'd':
        ok = (mkdirp(fullpath) == 0 || errno == EEXIST);
        break;
    case 's':
        {
            char target[PATH_MAX];
            if (!prompt_input("target: ", target, sizeof(target))) return;
            ok = (symlink(target, fullpath) == 0);
        }
        break;
    case 'h':
        {
            char target[PATH_MAX];
            if (!prompt_input("target: ", target, sizeof(target))) return;
            ok = (link(target, fullpath) == 0);
        }
        break;
    }

    if (ok) {
        read_dir(c);
        c->cur = find_entry(c, name);
        c->scroll = 0;
    }
}

/* Delete file/dir */
static void do_delete(Context *c, int force) {
    if (c->nentries == 0) return;
    Entry *e = &c->entries[c->cur];

    char fullpath[PATH_MAX];
    snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);

    if (!force) {
        char msg[PATH_MAX + 16];
        snprintf(msg, sizeof(msg), "rm -rf '%s'?", e->name);
        show_msg(msg);
        nodelay(mainwin, 0);
        int ch = wgetch(mainwin);
        if (ch != 'y' && ch != 'Y') return;
    }

    char cmd[PATH_MAX + 32];
    snprintf(cmd, sizeof(cmd), "rm -rf '%s'", fullpath);
    int r = system(cmd);
    if (r == 0) {
        read_dir(c);
        if (c->cur >= c->nentries) c->cur = c->nentries > 0 ? c->nentries - 1 : 0;
        c->scroll = 0;
    }
}

/* Rename/dup */
static void do_rename(Context *c) {
    if (c->nentries == 0) return;
    Entry *e = &c->entries[c->cur];

    /* Show current name as prompt */
    show_msg(e->name);

    char newname[NAME_MAX + 1];
    xstrlcpy(newname, e->name, sizeof(newname));

    /* Use a proper rename prompt */
    int row = LINES - 1;
    wmove(mainwin, row, 0);
    wclrtoeol(mainwin);

    /* Pre-fill with current name */
    int pos = strlen(newname);
    waddstr(mainwin, newname);
    wrefresh(mainwin);

    /* Input with pre-filled text */
    nodelay(mainwin, 0);
    int ch;
    while ((ch = wgetch(mainwin)) != ERR) {
        if (ch == '\n' || ch == KEY_ENTER) break;
        if (ch == 27) return;
        if (ch == KEY_BACKSPACE || ch == 127 || ch == 8) {
            if (pos > 0) {
                pos--;
                newname[pos] = '\0';
                wmove(mainwin, row, 0);
                wclrtoeol(mainwin);
                waddstr(mainwin, newname);
                wrefresh(mainwin);
            }
            continue;
        }
        if (ch >= 32 && ch < 127 && pos < NAME_MAX) {
            newname[pos++] = ch;
            newname[pos] = '\0';
            wmove(mainwin, row, 0);
            wclrtoeol(mainwin);
            waddstr(mainwin, newname);
            wrefresh(mainwin);
        }
    }

    if (!newname[0] || strcmp(newname, e->name) == 0) return;

    char oldpath[PATH_MAX], newpath[PATH_MAX];
    snprintf(oldpath, sizeof(oldpath), "%s/%s", c->path, e->name);
    snprintf(newpath, sizeof(newpath), "%s/%s", c->path, newname);

    if (rename(oldpath, newpath) == 0) {
        read_dir(c);
        c->cur = find_entry(c, newname);
        c->scroll = 0;
    }
}

/* Copy/move operations */
static void do_copy_move(Context *c, int move) {
    if (sel_n == 0) {
        show_msg("no selection");
        return;
    }

    const char *op = move ? "mv" : "cp";
    const char *advcpopt = cfg_advcpmv ? (move ? "-g" : "-g") : "";

    endwin();

    int ok = 1;
    for (int i = 0; i < sel_n; i++) {
        if (!sel_entries[i]) continue;
        char cmd[CMD_LEN];
        if (move)
            snprintf(cmd, sizeof(cmd), "mv %s '%s' '%s/' 2>&1", advcpopt, sel_entries[i], c->path);
        else
            snprintf(cmd, sizeof(cmd), "cp -r %s '%s' '%s/' 2>&1", advcpopt, sel_entries[i], c->path);
        int r = system(cmd);
        if (r != 0) ok = 0;
    }

    if (move) sel_clear();

    read_dir(c);
    c->scroll = 0;

    refresh();

    if (!ok) wait_for_key();
}

/* Bookmark handling */
static void do_bookmark(Context *c) {
    /* Show current dir name as bookmark name suggestion */
    char bname[NAME_MAX + 1];
    char *base = xbasename(c->path);
    xstrlcpy(bname, base, sizeof(bname));

    int row = LINES - 1;
    wmove(mainwin, row, 0);
    wclrtoeol(mainwin);
    wprintw(mainwin, "name: %s", bname);
    wrefresh(mainwin);

    nodelay(mainwin, 0);
    int ch = wgetch(mainwin);
    if (ch == 27) return;
    /* For simplicity, just show the bookmark */
}

/* Jump to entry by offset */
static void do_jump(Context *c) {
    /* Show entries with relative offsets */
    int listrows = LINES - 3;

    werase(mainwin);
    draw_header(c);
    wmove(mainwin, 1, 0); wclrtoeol(mainwin);

    int row = 2;
    for (int i = c->scroll; i < c->nentries && row < LINES - 1; i++, row++) {
        int off = i - c->cur;
        wmove(mainwin, row, 0);
        wclrtoeol(mainwin);
        if (off == 0)
            wprintw(mainwin, "%4d %s", off, c->entries[i].name);
        else
            wprintw(mainwin, "%+4d %s", off, c->entries[i].name);
        if (S_ISDIR(c->entries[i].sb.st_mode)) waddch(mainwin, '/');
    }

    show_msg("jump (+n/-n/n):");
    wrefresh(mainwin);

    char jbuf[16];
    prompt_input("jump (+n/-n/n): ", jbuf, sizeof(jbuf));
    if (!jbuf[0]) return;

    int off = atoi(jbuf);
    int newcur;
    if (jbuf[0] == '+' || jbuf[0] == '-')
        newcur = c->cur + off;
    else
        newcur = off - 1; /* 1-indexed absolute */

    if (newcur < 0) newcur = 0;
    if (newcur >= c->nentries) newcur = c->nentries - 1;
    c->cur = newcur;
    c->scroll = 0;
}

/* Session management */
static void do_session(Context *c) {
    show_msg("'s'ave/'l'oad/'r'estore?");
    nodelay(mainwin, 0);
    int ch = wgetch(mainwin);
    if (ch == 27) return;
    /* Session handling is complex, simplified here */
    (void)c;
}

/* Archive operation */
static void do_archive(Context *c) {
    if (c->nentries == 0) return;
    Entry *e = &c->entries[c->cur];
    char fullpath[PATH_MAX];
    snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);

    /* Simple archive creation */
    char arcname[PATH_MAX];
    snprintf(arcname, sizeof(arcname), "%s.tar.gz", fullpath);

    char cmd[CMD_LEN];
    if (cfg_bsdtar)
        snprintf(cmd, sizeof(cmd), "bsdtar -czf '%s' '%s' 2>&1", arcname, fullpath);
    else
        snprintf(cmd, sizeof(cmd), "tar -czf '%s' '%s' 2>&1", arcname, fullpath);

    endwin();
    int r = system(cmd);
    refresh();

    if (r == 0) {
        read_dir(c);
        c->scroll = 0;
    }
}

/* Select all / invert */
static void do_sel_all(Context *c, int invert) {
    char fullpath[PATH_MAX];
    for (int i = 0; i < c->nentries; i++) {
        snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, c->entries[i].name);
        if (invert) {
            if (c->entries[i].flags & 1) {
                c->entries[i].flags &= ~1;
                sel_remove(fullpath);
            } else {
                c->entries[i].flags |= 1;
                sel_add(fullpath);
            }
        } else {
            c->entries[i].flags |= 1;
            sel_add(fullpath);
        }
    }
    sync_sel();
}

/* Export list to file */
static void do_export(Context *c) {
    char fname[PATH_MAX];
    snprintf(fname, sizeof(fname), "%s/.nnn-list", gethomedir());

    FILE *fp = fopen(fname, "w");
    if (!fp) return;

    for (int i = 0; i < c->nentries; i++) {
        fprintf(fp, "%s/%s\n", c->path, c->entries[i].name);
    }
    fclose(fp);
}

/* Toggle executable bit */
static void do_toggle_exec(Context *c) {
    if (c->nentries == 0) return;
    Entry *e = &c->entries[c->cur];
    char fullpath[PATH_MAX];
    snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);

    mode_t mode = e->sb.st_mode;
    if (mode & (S_IXUSR | S_IXGRP | S_IXOTH)) {
        /* Remove execute */
        mode &= ~(S_IXUSR | S_IXGRP | S_IXOTH);
    } else {
        /* Add execute */
        mode |= (S_IXUSR | S_IXGRP | S_IXOTH);
    }
    chmod(fullpath, mode);
    lstat(fullpath, &e->sb);
}

