/* Filter mode */
static void do_filter(Context *c) {
    int row = LINES - 1;
    char fbuf[FILTER_LEN];
    xstrlcpy(fbuf, c->filter, sizeof(fbuf));

    /* Show filter prompt */
    const char *fmode = cfg_regex ? "re" : (cfg_fuzzy ? "fz" : "str");
    char prompt[64];
    snprintf(prompt, sizeof(prompt), " str [/], ic [:]");

    wmove(mainwin, row, 0);
    wclrtoeol(mainwin);
    /* Show on right side */
    int promptlen = strlen(prompt);
    wmove(mainwin, row, COLS - promptlen);
    waddstr(mainwin, prompt);
    wmove(mainwin, row, 0);
    waddch(mainwin, '/');
    waddstr(mainwin, fbuf);
    wrefresh(mainwin);

    /* Filter input loop */
    int pos = strlen(fbuf);
    nodelay(mainwin, 0);
    int ch;

    while ((ch = wgetch(mainwin)) != ERR) {
        if (ch == '\n' || ch == KEY_ENTER) break;
        if (ch == 27) {
            /* Escape - clear filter */
            fbuf[0] = '\0';
            pos = 0;
            break;
        }
        if (ch == KEY_BACKSPACE || ch == 127 || ch == 8) {
            if (pos > 0) {
                pos--;
                fbuf[pos] = '\0';
            } else {
                /* backspace on empty filter - exit filter mode */
                break;
            }
        } else if (ch >= 32 && ch < 127 && pos < FILTER_LEN - 1) {
            fbuf[pos++] = ch;
            fbuf[pos] = '\0';
        } else if (ch == KEY_UP || ch == 'k') {
            break;
        } else if (ch == KEY_DOWN || ch == 'j') {
            break;
        } else {
            continue;
        }

        /* Update filter and redisplay */
        xstrlcpy(c->filter, fbuf, sizeof(c->filter));
        int old_cur = c->cur;
        read_dir(c);

        /* Try to keep cursor on same entry */
        if (c->nentries > 0) {
            c->cur = 0;
            c->scroll = 0;
        }

        /* Check for auto-enter on unique match */
        if (!cfg_noautoenter && c->nentries == 1 &&
            S_ISDIR(c->entries[0].sb.st_mode)) {
            /* Auto-enter the directory */
            navigate_into(c);
            fbuf[0] = '\0';
            pos = 0;
            xstrlcpy(c->filter, fbuf, sizeof(c->filter));
        }

        /* Redraw */
        int listrows = LINES - 3;
        if (c->cur < c->scroll) c->scroll = c->cur;
        if (c->cur >= c->scroll + listrows) c->scroll = c->cur - listrows + 1;

        /* Redraw header and file list */
        draw_header(c);
        wmove(mainwin, 1, 0); wclrtoeol(mainwin);
        int r2 = 2;
        for (int i = c->scroll; i < c->nentries && r2 < LINES - 1; i++, r2++)
            draw_entry(c, r2, i);
        for (; r2 < LINES - 1; r2++) { wmove(mainwin, r2, 0); wclrtoeol(mainwin); }

        /* Show filter on status line */
        wmove(mainwin, row, 0);
        wclrtoeol(mainwin);
        int pl2 = strlen(prompt);
        wmove(mainwin, row, COLS - pl2);
        waddstr(mainwin, prompt);
        wmove(mainwin, row, 0);
        waddch(mainwin, '/');
        waddstr(mainwin, fbuf);
        wrefresh(mainwin);
    }

    /* Apply final filter */
    xstrlcpy(c->filter, fbuf, sizeof(c->filter));
    read_dir(c);
    if (c->cur >= c->nentries) c->cur = c->nentries > 0 ? c->nentries - 1 : 0;
    c->scroll = 0;
}

