/* Rename/dup */
static void do_rename(Context *c) {
    if (c->nentries == 0) return;
    Entry *e = &c->entries[c->cur];

    /* Show current name as prompt */
    show_msg(e->name);

    char newname[NAME_MAX + 1];
    xstrlcpy(newname, e->name, sizeof(newname));

    /* Use a proper rename prompt */
    int row = LINES - 1;
    wmove(mainwin, row, 0);
    wclrtoeol(mainwin);

    /* Pre-fill with current name */
    int pos = strlen(newname);
    waddstr(mainwin, newname);
    wrefresh(mainwin);

    /* Input with pre-filled text */
    nodelay(mainwin, 0);
    int ch;
    while ((ch = wgetch(mainwin)) != ERR) {
        if (ch == '\n' || ch == KEY_ENTER) break;
        if (ch == 27) return;
        if (ch == KEY_BACKSPACE || ch == 127 || ch == 8) {
            if (pos > 0) {
                pos--;
                newname[pos] = '\0';
                wmove(mainwin, row, 0);
                wclrtoeol(mainwin);
                waddstr(mainwin, newname);
                wrefresh(mainwin);
            }
            continue;
        }
        if (ch >= 32 && ch < 127 && pos < NAME_MAX) {
            newname[pos++] = ch;
            newname[pos] = '\0';
            wmove(mainwin, row, 0);
            wclrtoeol(mainwin);
            waddstr(mainwin, newname);
            wrefresh(mainwin);
        }
    }

    if (!newname[0] || strcmp(newname, e->name) == 0) return;

    char oldpath[PATH_MAX], newpath[PATH_MAX];
    snprintf(oldpath, sizeof(oldpath), "%s/%s", c->path, e->name);
    snprintf(newpath, sizeof(newpath), "%s/%s", c->path, newname);

    if (rename(oldpath, newpath) == 0) {
        read_dir(c);
        c->cur = find_entry(c, newname);
        c->scroll = 0;
    }
