/* Jump to entry by offset */
static void do_jump(Context *c) {
    /* Show entries with relative offsets */
    int listrows = LINES - 3;

    werase(mainwin);
    draw_header(c);
    wmove(mainwin, 1, 0); wclrtoeol(mainwin);

    int row = 2;
    for (int i = c->scroll; i < c->nentries && row < LINES - 1; i++, row++) {
        int off = i - c->cur;
        wmove(mainwin, row, 0);
        wclrtoeol(mainwin);
        if (off == 0)
            wprintw(mainwin, "%4d %s", off, c->entries[i].name);
        else
            wprintw(mainwin, "%+4d %s", off, c->entries[i].name);
        if (S_ISDIR(c->entries[i].sb.st_mode)) waddch(mainwin, '/');
    }

    show_msg("jump (+n/-n/n):");
    wrefresh(mainwin);

    char jbuf[16];
    prompt_input("jump (+n/-n/n): ", jbuf, sizeof(jbuf));
    if (!jbuf[0]) return;

    int off = atoi(jbuf);
    int newcur;
    if (jbuf[0] == '+' || jbuf[0] == '-')
        newcur = c->cur + off;
    else
        newcur = off - 1; /* 1-indexed absolute */

    if (newcur < 0) newcur = 0;
    if (newcur >= c->nentries) newcur = c->nentries - 1;
    c->cur = newcur;
    c->scroll = 0;
}

