/* Navigation functions */

/* Go to parent directory */
static void navigate_up(Context *c) {
    if (strcmp(c->path, "/") == 0) return;

    /* Save current dir name for restoration */
    char *basename = xbasename(c->path);
    xstrlcpy(c->lastname, basename, sizeof(c->lastname));

    /* Save last dir */
    xstrlcpy(c->lastdir, c->path, sizeof(c->lastdir));

    /* Go to parent */
    char parent[PATH_MAX];
    xstrlcpy(parent, c->path, sizeof(parent));
    char *p = strrchr(parent, '/');
    if (p) {
        if (p == parent)
            parent[1] = '\0';
        else
            *p = '\0';
    }

    xstrlcpy(c->path, parent, sizeof(c->path));
    c->filter[0] = '\0';
    read_dir(c);

    /* Restore position to the dir we came from */
    c->cur = find_entry(c, c->lastname);
    c->scroll = 0;
}

