    case 'e': c->sortby = SORT_EXT; break;
    case 'r': c->sortrev = !c->sortrev; break;
    case 's': c->sortby = SORT_SIZE; break;
    case 't': c->sortby = SORT_TIME; break;
    case 'v': c->sortby = SORT_VER; break;
    case 'c': c->sortby = SORT_NONE; c->sortrev = 0; c->du_mode = 0; break;
    case ('T' - 64): /* Ctrl-T */
        c->sortby = SORT_NONE; c->sortrev = 0; break;
    default: break;
    }
    sort_by = c->sortby;
    sort_rev = c->sortrev;
    if (c->nentries > 0)
