/* Create new file/dir */
static void do_create(Context *c) {
    show_msg("['f'ile]/'d'ir/'s'ym/'h'ard?");
    nodelay(mainwin, 0);
    int ch = wgetch(mainwin);
    if (ch == 27) return;

    char name[NAME_MAX + 1];
    char prompt2[32];
    switch (ch) {
    case 'f': strcpy(prompt2, "name: "); break;
    case 'd': strcpy(prompt2, "mkdir: "); break;
    case 's': strcpy(prompt2, "symlink: "); break;
    case 'h': strcpy(prompt2, "hardlink: "); break;
    default: return;
    }

    if (!prompt_input(prompt2, name, sizeof(name))) return;
    if (!name[0]) return;

    char fullpath[PATH_MAX];
    snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, name);

    int ok = 0;
    switch (ch) {
    case 'f':
        {
            int fd = open(fullpath, O_CREAT | O_WRONLY, 0644);
            if (fd >= 0) { close(fd); ok = 1; }
        }
        break;
    case 'd':
        ok = (mkdirp(fullpath) == 0 || errno == EEXIST);
        break;
    case 's':
        {
            char target[PATH_MAX];
            if (!prompt_input("target: ", target, sizeof(target))) return;
            ok = (symlink(target, fullpath) == 0);
        }
        break;
    case 'h':
        {
            char target[PATH_MAX];
            if (!prompt_input("target: ", target, sizeof(target))) return;
            ok = (link(target, fullpath) == 0);
        }
        break;
    }

    if (ok) {
        read_dir(c);
        c->cur = find_entry(c, name);
        c->scroll = 0;
    }
}

