/* Toggle executable bit */
static void do_toggle_exec(Context *c) {
    if (c->nentries == 0) return;
    Entry *e = &c->entries[c->cur];
    char fullpath[PATH_MAX];
    snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);

    mode_t mode = e->sb.st_mode;
    if (mode & (S_IXUSR | S_IXGRP | S_IXOTH)) {
        /* Remove execute */
        mode &= ~(S_IXUSR | S_IXGRP | S_IXOTH);
    } else {
        /* Add execute */
        mode |= (S_IXUSR | S_IXGRP | S_IXOTH);
    }
    chmod(fullpath, mode);
    lstat(fullpath, &e->sb);
}

