/* Navigation functions */

/* Go to parent directory */
static void navigate_up(Context *c) {
    if (strcmp(c->path, "/") == 0) return;

    /* Save current dir name for restoration */
    char *basename = xbasename(c->path);
    xstrlcpy(c->lastname, basename, sizeof(c->lastname));

    /* Save last dir */
    xstrlcpy(c->lastdir, c->path, sizeof(c->lastdir));

    /* Go to parent */
    char parent[PATH_MAX];
    xstrlcpy(parent, c->path, sizeof(parent));
    char *p = strrchr(parent, '/');
    if (p) {
        if (p == parent)
            parent[1] = '\0';
        else
            *p = '\0';
    }

    xstrlcpy(c->path, parent, sizeof(c->path));
    c->filter[0] = '\0';
    read_dir(c);

    /* Restore position to the dir we came from */
    c->cur = find_entry(c, c->lastname);
    c->scroll = 0;
}

/* Enter directory or open file */
static int navigate_into(Context *c) {
    if (c->nentries == 0) return 0;
    Entry *e = &c->entries[c->cur];

    char fullpath[PATH_MAX];
    snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);

    /* Check if it's a directory */
    struct stat sb;
    int isdir = 0;
    if (stat(fullpath, &sb) == 0 && S_ISDIR(sb.st_mode))
        isdir = 1;

    if (isdir) {
        xstrlcpy(c->lastdir, c->path, sizeof(c->lastdir));
        xstrlcpy(c->lastname, e->name, sizeof(c->lastname));
        xstrlcpy(c->path, fullpath, sizeof(c->path));
        c->filter[0] = '\0';
        read_dir(c);
        c->cur = 0;
        c->scroll = 0;
        return 1;
    } else {
        /* Open file */
        if (cfg_useeditor) {
            open_editor(fullpath);
        } else {
            open_file(c, fullpath);
        }
        /* Auto-advance on selection if enabled */
        if (!cfg_noadvance && cfg_picker) {
            /* Select and advance */
            toggle_sel(c);
            if (c->cur < c->nentries - 1)
                c->cur++;
        }
        return 0;
    }
}

