    int ch;
    while ((ch = wgetch(mainwin)) != ERR) {
        if (ch == '\n' || ch == KEY_ENTER) break;
        if (ch == 27) return;
        if (ch == KEY_BACKSPACE || ch == 127 || ch == 8) {
            if (pos > 0) {
                pos--;
                newname[pos] = '\0';
                wmove(mainwin, row, 0);
                wclrtoeol(mainwin);
                waddstr(mainwin, newname);
                wrefresh(mainwin);
            }
            continue;
        }
        if (ch >= 32 && ch < 127 && pos < NAME_MAX) {
            newname[pos++] = ch;
            newname[pos] = '\0';
            wmove(mainwin, row, 0);
            wclrtoeol(mainwin);
            waddstr(mainwin, newname);
            wrefresh(mainwin);
        }
    }

    if (!newname[0] || strcmp(newname, e->name) == 0) return;

    char oldpath[PATH_MAX], newpath[PATH_MAX];
    snprintf(oldpath, sizeof(oldpath), "%s/%s", c->path, e->name);
    snprintf(newpath, sizeof(newpath), "%s/%s", c->path, newname);

    if (rename(oldpath, newpath) == 0) {
        read_dir(c);
        c->cur = find_entry(c, newname);
        c->scroll = 0;
    }
}

/* Copy/move operations */
static void do_copy_move(Context *c, int move) {
    if (sel_n == 0) {
        show_msg("no selection");
        return;
    }

    const char *op = move ? "mv" : "cp";
    const char *advcpopt = cfg_advcpmv ? (move ? "-g" : "-g") : "";

    endwin();

    int ok = 1;
    for (int i = 0; i < sel_n; i++) {
        if (!sel_entries[i]) continue;
        char cmd[CMD_LEN];
        if (move)
            snprintf(cmd, sizeof(cmd), "mv %s '%s' '%s/' 2>&1", advcpopt, sel_entries[i], c->path);
        else
            snprintf(cmd, sizeof(cmd), "cp -r %s '%s' '%s/' 2>&1", advcpopt, sel_entries[i], c->path);
        int r = system(cmd);
        if (r != 0) ok = 0;
    }

    if (move) sel_clear();

    read_dir(c);
    c->scroll = 0;

    refresh();

    if (!ok) wait_for_key();
}

/* Bookmark handling */
static void do_bookmark(Context *c) {
    /* Show current dir name as bookmark name suggestion */
    char bname[NAME_MAX + 1];
    char *base = xbasename(c->path);
    xstrlcpy(bname, base, sizeof(bname));

    int row = LINES - 1;
    wmove(mainwin, row, 0);
    wclrtoeol(mainwin);
    wprintw(mainwin, "name: %s", bname);
    wrefresh(mainwin);

    nodelay(mainwin, 0);
    int ch = wgetch(mainwin);
    if (ch == 27) return;
    /* For simplicity, just show the bookmark */
}

/* Jump to entry by offset */
static void do_jump(Context *c) {
    /* Show entries with relative offsets */
    int listrows = LINES - 3;

    werase(mainwin);
    draw_header(c);
    wmove(mainwin, 1, 0); wclrtoeol(mainwin);

    int row = 2;
    for (int i = c->scroll; i < c->nentries && row < LINES - 1; i++, row++) {
        int off = i - c->cur;
        wmove(mainwin, row, 0);
        wclrtoeol(mainwin);
        if (off == 0)
            wprintw(mainwin, "%4d %s", off, c->entries[i].name);
        else
            wprintw(mainwin, "%+4d %s", off, c->entries[i].name);
        if (S_ISDIR(c->entries[i].sb.st_mode)) waddch(mainwin, '/');
    }

    show_msg("jump (+n/-n/n):");
    wrefresh(mainwin);

    char jbuf[16];
    prompt_input("jump (+n/-n/n): ", jbuf, sizeof(jbuf));
    if (!jbuf[0]) return;

    int off = atoi(jbuf);
    int newcur;
    if (jbuf[0] == '+' || jbuf[0] == '-')
        newcur = c->cur + off;
    else
        newcur = off - 1; /* 1-indexed absolute */

    if (newcur < 0) newcur = 0;
    if (newcur >= c->nentries) newcur = c->nentries - 1;
    c->cur = newcur;
    c->scroll = 0;
}

/* Session management */
static void do_session(Context *c) {
    show_msg("'s'ave/'l'oad/'r'estore?");
    nodelay(mainwin, 0);
    int ch = wgetch(mainwin);
    if (ch == 27) return;
    /* Session handling is complex, simplified here */
    (void)c;
}

/* Archive operation */
static void do_archive(Context *c) {
    if (c->nentries == 0) return;
    Entry *e = &c->entries[c->cur];
    char fullpath[PATH_MAX];
    snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);

    /* Simple archive creation */
    char arcname[PATH_MAX];
    snprintf(arcname, sizeof(arcname), "%s.tar.gz", fullpath);

    char cmd[CMD_LEN];
    if (cfg_bsdtar)
        snprintf(cmd, sizeof(cmd), "bsdtar -czf '%s' '%s' 2>&1", arcname, fullpath);
    else
        snprintf(cmd, sizeof(cmd), "tar -czf '%s' '%s' 2>&1", arcname, fullpath);

    endwin();
    int r = system(cmd);
    refresh();

    if (r == 0) {
        read_dir(c);
        c->scroll = 0;
    }
}

/* Select all / invert */
static void do_sel_all(Context *c, int invert) {
    char fullpath[PATH_MAX];
    for (int i = 0; i < c->nentries; i++) {
        snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, c->entries[i].name);
        if (invert) {
            if (c->entries[i].flags & 1) {
                c->entries[i].flags &= ~1;
                sel_remove(fullpath);
            } else {
                c->entries[i].flags |= 1;
                sel_add(fullpath);
            }
        } else {
            c->entries[i].flags |= 1;
            sel_add(fullpath);
        }
    }
    sync_sel();
}

/* Export list to file */
static void do_export(Context *c) {
    char fname[PATH_MAX];
    snprintf(fname, sizeof(fname), "%s/.nnn-list", gethomedir());

    FILE *fp = fopen(fname, "w");
    if (!fp) return;

    for (int i = 0; i < c->nentries; i++) {
        fprintf(fp, "%s/%s\n", c->path, c->entries[i].name);
    }
    fclose(fp);
}

/* Toggle executable bit */
static void do_toggle_exec(Context *c) {
    if (c->nentries == 0) return;
    Entry *e = &c->entries[c->cur];
    char fullpath[PATH_MAX];
    snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, e->name);

    mode_t mode = e->sb.st_mode;
    if (mode & (S_IXUSR | S_IXGRP | S_IXOTH)) {
        /* Remove execute */
        mode &= ~(S_IXUSR | S_IXGRP | S_IXOTH);
    } else {
        /* Add execute */
        mode |= (S_IXUSR | S_IXGRP | S_IXOTH);
    }
    chmod(fullpath, mode);
    lstat(fullpath, &e->sb);
}

