/* Context switching */
static void switch_context(int newcxt) {
    if (newcxt < 0 || newcxt >= CTX_MAX) return;
    if (newcxt == curcxt) return;

    /* Save current context state */
    /* (already saved in ctx[curcxt]) */

    curcxt = newcxt;

    if (!ctx[curcxt].active) {
        /* New context - start in same dir */
        xstrlcpy(ctx[curcxt].path, ctx[0].path, sizeof(ctx[curcxt].path));
        ctx[curcxt].active = 1;
        ctx[curcxt].sortby = cfg_sortby;
        ctx[curcxt].sortrev = cfg_sortrev;
        ctx[curcxt].showhidden = cfg_showhidden;
        ctx[curcxt].dtoggle = cfg_detail;
        ctx[curcxt].timetype = cfg_timetype;
