        read_dir(&ctx[curcxt]);
        ctx[curcxt].cur = 0;
        ctx[curcxt].scroll = 0;
    }
}

/* Cycle to next context */
static void cycle_context(int forward) {
    int n = forward ? 1 : -1;
    int next = (curcxt + n + CTX_MAX) % CTX_MAX;

    /* Find next active or wrap around */
    int tried = 0;
    while (tried < CTX_MAX) {
        if (next == curcxt) {
            /* Create new context */
            break;
        }
        if (ctx[next].active) break;
        next = (next + n + CTX_MAX) % CTX_MAX;
        tried++;
    }

    if (next == curcxt) {
        /* Create new context in next slot */
        next = (curcxt + 1) % CTX_MAX;
        if (!ctx[next].active) {
            switch_context(next);
            return;
        }
        /* Find first empty */
        for (int i = 0; i < CTX_MAX; i++) {
            if (!ctx[i].active && i != curcxt) {
                next = i;
                break;
            }
        }
    }

    switch_context(next);
}

/* Main input processing loop */
static void run_nnn(void) {
    Context *c = &ctx[curcxt];

    while (running) {
        if (sig_resize) {
            handle_resize();
        }

        redraw(c);

        /* Get key */
        nodelay(mainwin, 0);
        if (cfg_timeout > 0) {
            wtimeout(mainwin, cfg_timeout * 1000);
        }

        int ch = wgetch(mainwin);

        if (ch == ERR) {
            /* Timeout or error */
            continue;
        }

        c = &ctx[curcxt];

        /* Handle escape sequence */
        static int esc_count = 0;

        if (ch == 27) {
            /* ESC */
            esc_count++;
            if (esc_count >= 2) {
                esc_count = 0;
                /* 2xEsc = quit */
                quit_all = 1;
                running = 0;
                break;
            }
            /* Single ESC - clear filter or exit prompt */
            if (c->filter[0]) {
                c->filter[0] = '\0';
                read_dir(c);
                c->cur = 0;
                c->scroll = 0;
            }
            continue;
        }
        esc_count = 0;

        /* Type-to-nav mode */
        if (cfg_typetonav && ch >= 32 && ch < 127 && ch != '/' && ch != ':') {
            /* Add char to filter */
            int flen = strlen(c->filter);
            if (flen < FILTER_LEN - 1) {
                c->filter[flen] = ch;
                c->filter[flen + 1] = '\0';
                read_dir(c);
                if (c->nentries > 0) {
                    c->cur = 0;
                    c->scroll = 0;
                }
                continue;
            }
        }

        switch (ch) {
        /* Navigation */
        case KEY_UP:
        case 'k':
            if (c->cur > 0) {
                c->cur--;
            } else if (!cfg_norollover) {
                c->cur = c->nentries > 0 ? c->nentries - 1 : 0;
            }
            break;

        case KEY_DOWN:
        case 'j':
            if (c->cur < c->nentries - 1) {
                c->cur++;
            } else if (!cfg_norollover) {
                c->cur = 0;
            }
            break;

        case KEY_LEFT:
        case 'h':
            navigate_up(c);
            break;

        case KEY_RIGHT:
        case 'l':
        case '\n':
        case '\r':
        case KEY_ENTER:
            navigate_into(c);
            break;

        case 'g':
        case ('A' - 64): /* Ctrl-A */
            c->cur = 0;
            c->scroll = 0;
            break;

        case 'G':
        case ('E' - 64): /* Ctrl-E */
            c->cur = c->nentries > 0 ? c->nentries - 1 : 0;
            c->scroll = 0;
            break;

        case KEY_PPAGE:
        case ('U' - 64): /* Ctrl-U */
            {
                int pg = cfg_scrolllines > 0 ? cfg_scrolllines : (LINES - 3) / 2;
                c->cur -= pg;
                if (c->cur < 0) c->cur = 0;
                c->scroll -= pg;
                if (c->scroll < 0) c->scroll = 0;
            }
            break;

        case KEY_NPAGE:
        case ('D' - 64): /* Ctrl-D */
            {
                int pg = cfg_scrolllines > 0 ? cfg_scrolllines : (LINES - 3) / 2;
                c->cur += pg;
                if (c->cur >= c->nentries) c->cur = c->nentries > 0 ? c->nentries - 1 : 0;
            }
            break;

        case '~':
            navigate_home(c);
            break;

        case '@':
            navigate_root(c);
            break;

        case '-':
            navigate_prev(c);
            break;

        case '\'':
            /* First file/match */
            c->cur = 0;
            c->scroll = 0;
            break;

        case 'J':
            do_jump(c);
            break;

        case ('J' - 64): /* Ctrl-J */
            cfg_noadvance = !cfg_noadvance;
            break;

        /* Context switching */
        case '1': case '2': case '3': case '4':
        case '5': case '6': case '7': case '8':
            switch_context(ch - '1');
            c = &ctx[curcxt];
            break;

        case '\t':
            cycle_context(1);
            c = &ctx[curcxt];
            break;

        case KEY_BTAB:
            cycle_context(0);
            c = &ctx[curcxt];
            break;

        /* Quit */
        case 'q':
            if (ctx[curcxt].active) {
                /* Quit this context */
                ctx[curcxt].active = 0;
                /* Find another active context */
                int found = -1;
                for (int i = 0; i < CTX_MAX; i++) {
                    if (i != curcxt && ctx[i].active) {
                        found = i;
                        break;
                    }
                }
                if (found >= 0) {
                    curcxt = found;
                    c = &ctx[curcxt];
                } else {
                    running = 0;
                }
            } else {
                running = 0;
            }
            break;

        case ('Q' - 64): /* Ctrl-Q */
            quit_all = 1;
            running = 0;
            break;

        case 'Q':
            /* Pick/err quit */
            if (cfg_picker) {
                sel_write(picker_file, cfg_nullsep);
            }
            running = 0;
            break;

        case ('G' - 64): /* Ctrl-G - QuitCD */
            running = 0;
            break;

        /* Filter */
        case '/':
            do_filter(c);
            break;

        case '.':
            c->showhidden = !c->showhidden;
            read_dir(c);
            if (c->cur >= c->nentries) c->cur = c->nentries > 0 ? c->nentries - 1 : 0;
            c->scroll = 0;
            break;

        case ('N' - 64): /* Ctrl-N */
            cfg_typetonav = !cfg_typetonav;
            break;

        /* Files */
        case 'o':
        case ('O' - 64):
            if (c->nentries > 0) {
                char fullpath[PATH_MAX];
                snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, c->entries[c->cur].name);
                open_file(c, fullpath);
            }
            break;

        case 'f':
        case ('F' - 64):
            show_file_stats(c);
            break;

        case 'd':
            c->dtoggle = !c->dtoggle;
            break;

        case ('R' - 64): /* Ctrl-R rename/dup */
            do_rename(c);
            break;

        case 'r':
            /* Batch rename */
            {
                char cmd[CMD_LEN];
                char tmpfile[PATH_MAX];
                snprintf(tmpfile, sizeof(tmpfile), "/tmp/nnn-rename-%d", (int)getpid());
                FILE *fp = fopen(tmpfile, "w");
                if (fp) {
                    for (int i = 0; i < c->nentries; i++)
                        fprintf(fp, "%s\n", c->entries[i].name);
                    fclose(fp);
                    open_editor(tmpfile);
                    /* Apply renames... simplified */
                    unlink(tmpfile);
                }
            }
            break;

        case 'z':
            do_archive(c);
            break;

        case 'e':
            if (c->nentries > 0) {
                char fullpath[PATH_MAX];
                snprintf(fullpath, sizeof(fullpath), "%s/%s", c->path, c->entries[c->cur].name);
                open_editor(fullpath);
            }
            break;

        case '*':
            do_toggle_exec(c);
            break;

        case '>':
            do_export(c);
            break;

        case ' ':
        case '+':
            toggle_sel(c);
            if (!cfg_noadvance) {
                if (c->cur < c->nentries - 1) c->cur++;
            }
            break;

        case 'a':
            do_sel_all(c, 0);
            break;

        case 'A':
            do_sel_all(c, 1);
            break;

        case 'p':
        case ('P' - 64):
            do_copy_move(c, 0);
            break;

        case 'v':
        case ('V' - 64):
            do_copy_move(c, 1);
            break;

        case 'x':
        case ('X' - 64):
            {
                /* Delete with trash or rm */
                if (c->nentries > 0) {
                    Entry *e = &c->entries[c->cur];
                    char msg[NAME_MAX + 16];
                    snprintf(msg, sizeof(msg), "rm -rf '%s'?", e->name);
                    show_msg(msg);
                    nodelay(mainwin, 0);
                    int conf = wgetch(mainwin);
                    if (conf == 'y' || conf == 'Y') {
                        do_delete(c, 1);
                    }
                }
            }
            break;

        case 'X':
            do_delete(c, 1);
            break;

        case 'S':
            /* Listed sel size */
            {
                off_t total = 0;
                for (int i = 0; i < sel_n; i++) {
                    if (sel_entries[i]) {
                        struct stat sb;
                        if (stat(sel_entries[i], &sb) == 0)
                            total += sb.st_size;
                    }
                }
                char szstr[32];
                fmtsize(total, szstr, sizeof(szstr));
                char msg[64];
                snprintf(msg, sizeof(msg), "selection: %s", szstr);
                show_msg(msg);
                nodelay(mainwin, 0);
                wgetch(mainwin);
            }
            break;

        /* Misc */
        case '=':
            /* Launch app */
            {
                char app[CMD_LEN];
                if (prompt_input("app: ", app, sizeof(app)) && app[0]) {
                    endwin();
                    char cmd[CMD_LEN];
                    snprintf(cmd, sizeof(cmd), "cd '%s' && %s", c->path, app);
                    int r = system(cmd);
                    if (r != 0) {
                        printf("\n'Enter' to continue\n");
                        getchar();
                    }
                    refresh();
                }
            }
            break;

        case '!':
        case (']' - 64 + 1): /* Ctrl-] */
            spawn_shell(c->path);
            read_dir(c);
            break;

        case ']':
            run_cmd_prompt(c);
            read_dir(c);
            break;

        case 'c':
            /* Connect remote */
            show_msg("remote connect not available");
            break;

        case 'u':
            /* Unmount */
            show_msg("unmount not available");
            break;

        case 't':
            do_sort_toggle(c);
            break;

        case ('T' - 64): /* Ctrl-T */
            c->sortby = SORT_NONE;
            c->sortrev = 0;
            sort_by = c->sortby;
            sort_rev = c->sortrev;
            if (c->nentries > 0)
                qsort(c->entries, c->nentries, sizeof(Entry), entry_cmp);
            break;

        case 'T':
            do_time_type(c);
            break;

        case 's':
            do_session(c);
            break;

        case '0':
            /* Lock terminal */
            show_msg("locked - press any key");
            nodelay(mainwin, 0);
            wgetch(mainwin);
            break;

        case ('L' - 64): /* Ctrl-L */
            /* Redraw */
            clearok(mainwin, 1);
            break;

        case 'n':
            do_create(c);
            break;

        case 'B':
            do_bookmark(c);
            break;

        case '?':
            show_help(c);
            break;

        case ('Y' - 64): /* Ctrl-Y next young */
            /* Simplified - just move to next */
            if (c->cur < c->nentries - 1) c->cur++;
            break;

        case 'w':
        case ('W' - 64): /* Ctrl-W */
            /* Cp/mv sel as */
            show_msg("cp/mv sel as: not implemented");
            break;

        case 'E':
            /* Edit sel list */
            show_msg("edit sel list: not implemented");
            break;

        case KEY_RESIZE:
            handle_resize();
            break;

        default:
            break;
        }

        /* Handle page up/down for scroll */
        {
            int listrows = LINES - 3;
            if (c->cur < c->scroll)
                c->scroll = c->cur;
            if (c->cur >= c->scroll + listrows)
                c->scroll = c->cur - listrows + 1;
            if (c->scroll < 0) c->scroll = 0;
        }
    }
}

