        ctx[curcxt].du_mode = 0;
        read_dir(&ctx[curcxt]);
        ctx[curcxt].cur = 0;
        ctx[curcxt].scroll = 0;
    }
}

/* Cycle to next context */
static void cycle_context(int forward) {
    int n = forward ? 1 : -1;
    int next = (curcxt + n + CTX_MAX) % CTX_MAX;

    /* Find next active or wrap around */
    int tried = 0;
    while (tried < CTX_MAX) {
        if (next == curcxt) {
            /* Create new context */
            break;
        }
        if (ctx[next].active) break;
        next = (next + n + CTX_MAX) % CTX_MAX;
        tried++;
    }

    if (next == curcxt) {
        /* Create new context in next slot */
        next = (curcxt + 1) % CTX_MAX;
        if (!ctx[next].active) {
            switch_context(next);
            return;
        }
        /* Find first empty */
        for (int i = 0; i < CTX_MAX; i++) {
            if (!ctx[i].active && i != curcxt) {
                next = i;
                break;
            }
        }
    }

    switch_context(next);
}

