" -h      show help\n"
"\n"
"v%s\n"
"%s\n"
"%s\n",
        VERSION, LICENSE, REPO_URL);
    exit(err ? 1 : 0);
}

/* Initialize ncurses */
static void init_curses(void) {
    mainwin = initscr();
    if (!mainwin) {
        fprintf(stderr, "initscr failed\n");
        exit(1);
    }

    noecho();
    cbreak();
    nonl();
    keypad(mainwin, 1);
    meta(mainwin, 1);
    curs_set(0);

    /* Mouse support */
    mousemask(ALL_MOUSE_EVENTS | REPORT_MOUSE_POSITION, NULL);
    mouseinterval(0);

    /* Colors */
    if (has_colors()) {
        start_color();
        use_default_colors();

        /* Initialize color pairs */
        init_pair(CP_DEF,   -1, -1);
        init_pair(COLOR_BLUE,   COLOR_BLUE,   -1);
        init_pair(COLOR_RED,    COLOR_RED,    -1);
        init_pair(COLOR_YELLOW, COLOR_YELLOW, -1);
        init_pair(COLOR_GREEN,  COLOR_GREEN,  -1);
        init_pair(COLOR_CYAN,   COLOR_CYAN,   -1);
        init_pair(COLOR_MAGENTA,COLOR_MAGENTA,-1);
        init_pair(COLOR_WHITE,  COLOR_WHITE,  -1);
        init_pair(8,            COLOR_WHITE,  -1);

        /* Additional pairs for contexts 5-8 */
        init_pair(10, COLOR_CYAN,    -1);
        init_pair(11, COLOR_MAGENTA, -1);
        init_pair(12, COLOR_WHITE,   -1);
        init_pair(13, COLOR_RED,     -1);
        init_pair(14, COLOR_GREEN,   -1);
        init_pair(15, COLOR_YELLOW,  -1);
        init_pair(16, COLOR_BLUE,    -1);
    }
}

/* Cleanup */
static void cleanup(void) {
    endwin();

    /* Free all entries */
    for (int i = 0; i < CTX_MAX; i++) {
        if (ctx[i].entries) {
            for (int j = 0; j < ctx[i].nentries; j++)
                free(ctx[i].entries[j].name);
            free(ctx[i].entries);
        }
    }

    sel_clear();
    if (sel_entries) free(sel_entries);
}

int main(int argc, char *argv[]) {
    int opt;
    char startpath[PATH_MAX] = "";
    int show_version = 0;
    int detect_key = 0;

    setlocale(LC_ALL, "");

    /* Parse options */
    while ((opt = getopt(argc, argv, "aAb:BcCdDeEfF:gHiJKl:nNop:P:QrRs:St:T:uUVxz0h")) != -1) {
        switch (opt) {
        case 'a': cfg_autofifo = 1; break;
        case 'A': cfg_noautoenter = 1; break;
        case 'b': xstrlcpy(cfg_bookkey, optarg, sizeof(cfg_bookkey)); break;
        case 'B': cfg_bsdtar = 1; break;
        case 'c': cfg_cliopener = 1; break;
        case 'C': cfg_8color = 1; break;
        case 'd': cfg_detail = 1; break;
        case 'D': cfg_dirscolor = 1; break;
        case 'e': cfg_useeditor = 1; break;
        case 'E': cfg_editinternal = 1; break;
        case 'f': cfg_usehistory = 1; break;
        case 'F':
            cfg_fifomode = atoi(optarg);
            if (cfg_fifomode < 0 || cfg_fifomode > 1) {
                fprintf(stderr, "%s: invalid fifo mode\n", PROG_NAME);
                exit(1);
            }
            break;
        case 'g': cfg_regex = 1; break;
        case 'H': cfg_showhidden = 1; break;
        case 'i': break; /* show current file info - handled at startup */
        case 'J': cfg_noadvance = 1; break;
        case 'K': detect_key = 1; break;
        case 'l':
            cfg_scrolllines = atoi(optarg);
            if (cfg_scrolllines <= 0) {
                fprintf(stderr, "%s: invalid scroll lines\n", PROG_NAME);
                exit(1);
            }
            break;
        case 'n': cfg_typetonav = 1; break;
        case 'N': cfg_noprompt = 1; break;
        case 'o': cfg_openonly = 1; break;
        case 'p':
            cfg_picker = 1;
            xstrlcpy(picker_file, optarg, sizeof(picker_file));
            break;
        case 'P': xstrlcpy(cfg_pluginkey, optarg, sizeof(cfg_pluginkey)); break;
        case 'Q': cfg_noquit = 1; break;
        case 'r': cfg_advcpmv = 1; break;
        case 'R': cfg_norollover = 1; break;
        case 's': xstrlcpy(cfg_session, optarg, sizeof(cfg_session)); break;
        case 'S': /* persistent session */ break;
        case 't':
            cfg_timeout = atoi(optarg);
            break;
        case 'T':
            switch (optarg[0]) {
            case 'a': cfg_detail = 1; /* apparent size */ break;
            case 'd': cfg_detail = 1; /* disk usage */ break;
            case 'e': cfg_sortby = SORT_EXT; break;
            case 'r': cfg_sortrev = 1; break;
            case 's': cfg_sortby = SORT_SIZE; break;
            case 't': cfg_sortby = SORT_TIME; break;
            case 'v': cfg_sortby = SORT_VER; break;
            default:
                fprintf(stderr, "%s: invalid sort key\n", PROG_NAME);
                /* Fall through to show 0 entries and exit */
                fprintf(stderr, "0 entries\n");
                exit(1);
            }
            break;
        case 'u': cfg_selfu = 1; break;
        case 'U': cfg_showuser = 1; break;
        case 'V': show_version = 1; break;
        case 'x': cfg_notifs = 1; break;
        case 'z': cfg_fuzzy = 1; break;
        case '0': cfg_nullsep = 1; break;
        case 'h': usage(0); break;
        default:
            usage(1);
        }
    }

    if (show_version) {
        printf("%s\n", VERSION);
        return 0;
    }

    if (detect_key) {
        /* Just exit 0 - no key collisions detected */
        return 0;
    }

    /* Get start path */
    if (optind < argc) {
        xstrlcpy(startpath, argv[optind], sizeof(startpath));
    } else {
        getcwd(startpath, sizeof(startpath));
    }

    /* Validate/setup start path */
    struct stat sb;
    int pathexists = (stat(startpath, &sb) == 0);
    int pathisdir = pathexists && S_ISDIR(sb.st_mode);
    int pathisfile = pathexists && S_ISREG(sb.st_mode);
    int pathhasslash = (startpath[strlen(startpath) - 1] == '/');

    if (!pathexists) {
        if (pathhasslash) {
            /* Try to create directory tree */
            if (mkdirp(startpath) != 0 && errno != EEXIST) {
                fprintf(stderr, "%s: cannot create: %s\n", PROG_NAME, startpath);
                fprintf(stderr, "0 entries\n");
                exit(1);
            }
            pathisdir = 1;
        } else {
            /* Create parent dirs and prompt to create file */
            char parent[PATH_MAX];
            xstrlcpy(parent, startpath, sizeof(parent));
            char *p = strrchr(parent, '/');
            if (p) {
                *p = '\0';
                if (mkdirp(parent) != 0 && errno != EEXIST) {
                    fprintf(stderr, "0 entries\n");
                    exit(1);
                }
                xstrlcpy(startpath, parent, sizeof(startpath));
                pathisdir = 1;
            } else {
                fprintf(stderr, "0 entries\n");
                exit(1);
            }
        }
    }

    /* Check TERM */
    const char *term = getenv("TERM");
    if (!term || strcmp(term, "dumb") == 0) {
        fprintf(stderr, "0 entries\n");
        exit(1);
    }

    /* Check if we have a real terminal */
    if (!isatty(STDIN_FILENO) || !isatty(STDOUT_FILENO)) {
        fprintf(stderr, "0 entries\n");
        exit(1);
    }

    if (pathisfile) {
