    init_curses();

    /* Main loop */
    run_nnn();

    /* Cleanup */
    cleanup();

    /* Write selection if picker mode */
    if (cfg_picker && sel_n > 0) {
        sel_write(picker_file, cfg_nullsep);
    }

    return 0;
