# Also fix the status bar symlink time - it should use lstat time for symlinks in status bar
# Let me check what the original shows:
# Status: "1/22  2026-04-17 16:31 lrwxr-xr-x 7B ->usr/bin"
# bin symlink lstat time: Apr 10 02:21 - but original shows Apr 17 16:31
# Apr 17 16:31 matches the TARGET time (st_mtime of /usr/bin)
# So status bar uses TARGET time for symlinks too

cat > /tmp/fix_status_sym_time.py << 'EOF'
with open('/workspace/nnn.c', 'r') as f:
    content = f.read()

# Fix status bar time for symlinks
old = '''        /* Time */
        char tmbuf[32];
        time_t t = get_entry_time(e);
        fmt_time(t, tmbuf, sizeof(tmbuf));
        wattron(mainwin, A_REVERSE);
        wprintw(mainwin, "%s", tmbuf);
        wattroff(mainwin, A_REVERSE);'''

new = '''        /* Time - for symlinks, use target time */
        char tmbuf[32];
        time_t t;
        int islink_st = (e->flags & 2);
        if (islink_st && (e->flags & 4)) {
            /* Use target time */
            switch (cfg_timetype) {
            case TIME_ACCESS: t = e->tsb.st_atime; break;
            case TIME_CHANGE: t = e->tsb.st_ctime; break;
            default:          t = e->tsb.st_mtime; break;
            }
        } else {
            t = get_entry_time(e);
        }
        fmt_time(t, tmbuf, sizeof(tmbuf));
        wattron(mainwin, A_REVERSE);
        wprintw(mainwin, "%s", tmbuf);
        wattroff(mainwin, A_REVERSE);'''

content = content.replace(old, new, 1)
with open('/workspace/nnn.c', 'w') as f:
    f.write(content)
print("Done")
EOF
