echo "Running comprehensive tests..."

# Test 1: Basic dir listing
tmux new-session -d -s t -x 200 -y 50 2>&1
for test_name in "basic" "detail" "hidden" "hidden_detail" "sort_s" "sort_t" "sort_e" "sort_v" "sort_r" "showuser" "du_mode" "au_mode"; do
    case $test_name in
        basic)         ARGS="" ;;
        detail)        ARGS="-d" ;;
        hidden)        ARGS="-H" ;;
        hidden_detail) ARGS="-H -d" ;;
        sort_s)        ARGS="-T s" ;;
        sort_t)        ARGS="-T t" ;;
        sort_e)        ARGS="-T e" ;;
        sort_v)        ARGS="-T v" ;;
        sort_r)        ARGS="-T r" ;;
        showuser)      ARGS="-U -d" ;;
        du_mode)       ARGS="-T d" ;;
        au_mode)       ARGS="-T a" ;;
    esac

    tmux send-keys -t t "TERM=xterm ./executable $ARGS /tmp/test_nnn_dir" Enter
    sleep 2
    tmux capture-pane -t t -p > /tmp/orig_${test_name}.txt
    tmux send-keys -t t "q" ""; sleep 0.3

    tmux send-keys -t t "TERM=xterm /workspace/executable_test $ARGS /tmp/test_nnn_dir" Enter
    sleep 2
    tmux capture-pane -t t -p > /tmp/new_${test_name}.txt
    tmux send-keys -t t "q" ""; sleep 0.3

    # Compare (ignoring dynamic parts like volume/avail)
    if diff <(grep -v "avail:" /tmp/orig_${test_name}.txt) \
            <(grep -v "avail:" /tmp/new_${test_name}.txt) > /dev/null 2>&1; then
        echo "PASS: $test_name"
    else
        echo "FAIL: $test_name"
        diff <(grep -v "avail:" /tmp/orig_${test_name}.txt) \
             <(grep -v "avail:" /tmp/new_${test_name}.txt) | head -5
    fi
done
tmux kill-session -t t 2>&1

